	public static function get($name, $class = '')
	{
		if (!isset(self::$icons[$name])) {
			return '';
		}
		return '<svg class="nss-icon ' . esc_attr($class) . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . self::$icons[$name] . '</svg>';
	}
